[package]
name = "zip-password-finder"
version = "0.11.1"
description = "Find the password of protected ZIP files"
authors = ["Arnaud Gourlay <arnaud.gourlay@gmail.com>"]
repository = "https://github.com/agourlay/zip-password-finder"
license = "Apache-2.0"
readme = "README.md"
categories = ["command-line-interface"]
keywords = ["zip", "archive", "password", "crack", "brute-force"]
edition = "2024"

[dependencies]
zip = "8.6.0"
pbkdf2 = "0.13.0"                               # parallel version did not help the performance
hmac = "0.13.0"
sha1 = "0.11.0"
clap = { version = "4.6.1", features = ["cargo"] }
indicatif = "0.18.4"
thiserror = "2.0.18"
num_cpus = "1.17.0"
humantime = "2.3.0"
ctrlc = "3.5"
either = "1.15.0"

[profile.release]
lto = "fat"
codegen-units = 1

[profile.test]
opt-level = 3 # needed for fast execution

[dev-dependencies]
criterion = { version = "0.8.2", default-features = false, features = [
    "cargo_bench_support",
    "html_reports",
] }

[profile.bench]
debug = true

[[bench]]
name = "password_generator"
harness = false

[[bench]]
name = "password_reader"
harness = false
mod args;
mod charsets;
mod finder_errors;
mod password_finder;
mod password_gen;
mod password_mask;
mod password_reader;
mod password_worker;
mod zip_utils;

use crate::args::{Arguments, get_args};
use crate::finder_errors::FinderError;
use crate::password_finder::Strategy::{GenPasswords, MaskGenPasswords, PasswordFile};
use crate::password_finder::password_finder;

use crate::charsets::charset_from_choice;
use crate::password_mask::parse_mask;
use std::path::Path;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};

fn main() {
    let result = main_result();
    std::process::exit(match result {
        Ok(()) => 0,
        Err(err) => {
            eprintln!("{err}");
            1
        }
    });
}

fn main_result() -> Result<(), FinderError> {
    // CLI args
    let Arguments {
        input_file,
        workers,
        charset_choice,
        min_password_len,
        max_password_len,
        file_number,
        password_dictionary,
        starting_password,
        mask,
        custom_charsets,
    } = get_args()?;

    let strategy = if let Some(dict_path) = password_dictionary {
        let path = Path::new(&dict_path);
        PasswordFile(path.to_path_buf())
    } else if let Some(mask_pattern) = mask {
        let mask = parse_mask(&mask_pattern, &custom_charsets)?;
        MaskGenPasswords { mask }
    } else {
        let charset = charset_from_choice(&charset_choice)?;
        GenPasswords {
            charset,
            min_password_len,
            max_password_len,
            starting_password,
        }
    };

    // use physical cores by default to avoid issues with hyper-threading
    let workers = workers.unwrap_or_else(num_cpus::get_physical);
    let start_time = std::time::Instant::now();

    // stop signals to shut down threads
    let stop_signal = Arc::new(AtomicBool::new(false));

    // Intercept Ctrl-C signal to stop workers manually
    let stop_signal_interrupt = stop_signal.clone();
    ctrlc::set_handler(move || stop_signal_interrupt.store(true, Ordering::Relaxed))
        .expect("Error setting Ctrl-C handler");

    let password = password_finder(&input_file, workers, file_number, &strategy, stop_signal)?;
    let elapsed = start_time.elapsed();
    // display pretty time
    let elapsed = humantime::format_duration(elapsed);
    println!("Time elapsed: {elapsed}");
    match password {
        Some(password) => println!("Password found:{password}"),
        None => println!("Password not found"),
    }
    Ok(())
}

